async function main() {
 const cases = [['GET 200','get','/request-sample.json'],['POST 200','post','/__test__/echo'],['404','get','/__missing__'],['429','get','/__test__/status?code=429'],['500','get','/__test__/status?code=500'],['timeout','get','/__test__/delay?ms=1200'],['unapproved','get','http://127.0.0.1:43121/request-sample.json']];
 const results=[];
 for(const [id,method,path] of cases){
  const url=path.startsWith('http')?path:'http://127.0.0.1:43111'+path;
  try{const r=method==='post'?await axiosx.post(url,{hello:'Worker'},{timeout:5000}):await axiosx.get(url,{timeout:id==='timeout'?100:5000});results.push({id,status:r.status,data:r.data,headers:r.headers});}
  catch(e){results.push({id,code:e.code,message:e.message,cause:e.cause});}
 }
 return results;
}
